export const IDIOMS: Idiom[] = [{"id":251,"phrase":"read the room","meaning_cn":"察言观色；读懂气氛","meaning_en":"To understand the mood or feelings of the people around you.","example":"You need to read the room before cracking jokes at a funeral.","example_cn":"在葬礼上讲笑话之前，你得先察言观色。"},{"id":252,"phrase":"throw shade","meaning_cn":"公开嘲讽；暗中挖苦","meaning_en":"To publicly criticize or show disrespect toward someone.","example":"She was throwing shade at her rival during the interview.","example_cn":"她在采访中暗中挖苦了她的对手。"},{"id":253,"phrase":"spill the tea","meaning_cn":"爆料八卦；分享内幕消息","meaning_en":"To share gossip or reveal juicy information.","example":"Come on, spill the tea — what happened at the party?","example_cn":"快说说，派对上到底发生了什么？"},{"id":254,"phrase":"it is what it is","meaning_cn":"事已至此；就是这样了","meaning_en":"Accepting a situation that cannot be changed.","example":"The flight got canceled — it is what it is, let us find a hotel.","example_cn":"航班取消了——既然如此，我们找个酒店吧。"},{"id":255,"phrase":"main character energy","meaning_cn":"主角光环；活出自信的样子","meaning_en":"Acting as if you are the star of your own movie; supreme confidence.","example":"She walked into the office with main character energy today.","example_cn":"她今天走进办公室的样子自信满满，像自带主角光环。"},{"id":256,"phrase":"hit different","meaning_cn":"感觉特别不一样；格外触动人","meaning_en":"To have a stronger or more meaningful emotional impact than usual.","example":"That song hits different when you are going through a breakup.","example_cn":"分手的时候听那首歌，感觉完全不一样。"},{"id":257,"phrase":"living rent-free","meaning_cn":"一直住在脑海里；挥之不去","meaning_en":"Something that constantly occupies your thoughts.","example":"That embarrassing moment is living rent-free in my head.","example_cn":"那个尴尬的瞬间一直在我脑海里挥之不去。"},{"id":258,"phrase":"no cap","meaning_cn":"不骗你；说真的","meaning_en":"No lie; I am being completely honest.","example":"That was the best pizza I have ever had, no cap.","example_cn":"那是我吃过最好吃的披萨，说真的。"},{"id":259,"phrase":"slay","meaning_cn":"太厉害了；杀疯了","meaning_en":"To do something exceptionally well; to look amazing.","example":"You absolutely slayed that presentation!","example_cn":"你那个演讲真的太厉害了！"},{"id":260,"phrase":"gaslight","meaning_cn":"精神控制；让人质疑自己的判断","meaning_en":"To manipulate someone into doubting their own reality.","example":"Stop trying to gaslight me — I know what I saw.","example_cn":"别想让我怀疑自己——我知道我看到了什么。"},{"id":261,"phrase":"the ick","meaning_cn":"突然对某人产生的反感","meaning_en":"A sudden feeling of disgust or turn-off toward someone.","example":"He chewed with his mouth open and I got the ick.","example_cn":"他吃饭不闭嘴，我一下子就反感了。"},{"id":262,"phrase":"touch grass","meaning_cn":"出去走走；别上网了","meaning_en":"Go outside; disconnect from the internet and engage with the real world.","example":"You have been arguing online all day — go touch grass.","example_cn":"你在网上吵了一整天了——出去走走吧。"},{"id":263,"phrase":"vibe check","meaning_cn":"感觉检测；看看气氛怎么样","meaning_en":"An informal assessment of the mood or energy of a situation.","example":"Before we commit, let me do a vibe check on this restaurant.","example_cn":"在我们决定之前，让我先看看这家餐厅的氛围怎么样。"},{"id":264,"phrase":"understood the assignment","meaning_cn":"完全理解了要做什么；表现完美","meaning_en":"Did exactly what was needed; performed perfectly for the occasion.","example":"Her outfit for the gala? She understood the assignment.","example_cn":"她出席晚会的穿搭？简直完美到位。"},{"id":265,"phrase":"send it","meaning_cn":"冲了；放手去做","meaning_en":"To go for it without hesitation; commit fully to an action.","example":"Should I apply for that job? — Absolutely, send it!","example_cn":"我要不要申请那份工作？——当然，直接冲！"},{"id":266,"phrase":"caught in 4K","meaning_cn":"人赃俱获；被抓了个正着","meaning_en":"Caught doing something wrong with undeniable evidence.","example":"He said he was sick, but we caught him in 4K at the beach.","example_cn":"他说他生病了，但我们拍到他在海滩上了，抓了个正着。"},{"id":267,"phrase":"that tracks","meaning_cn":"说得通；和我了解的一致","meaning_en":"That makes sense; that is consistent with what I know.","example":"She always oversleeps? Yeah, that tracks.","example_cn":"她总是睡过头？嗯，说得通。"},{"id":268,"phrase":"era","meaning_cn":"时代；人生阶段（某种状态）","meaning_en":"A phase of life or personal identity someone is embracing.","example":"I am in my fitness era — gym every morning at 5 AM.","example_cn":"我现在处于健身阶段——每天早上5点去健身房。"},{"id":269,"phrase":"gate-keep","meaning_cn":"把持资源；设门槛排斥别人","meaning_en":"To control access to resources, communities, or knowledge; be exclusive.","example":"Stop gate-keeping that recipe — just share it with everyone.","example_cn":"别藏着那个食谱了——分享给大家吧。"},{"id":270,"phrase":"ate and left no crumbs","meaning_cn":"表现完美无缺；无可挑剔","meaning_en":"Performed so well there was nothing to criticize.","example":"Her speech at the conference? She ate and left no crumbs.","example_cn":"她在会议上的发言？简直无可挑剔。"},{"id":271,"phrase":"rent-free in my head","meaning_cn":"在脑子里挥之不去","meaning_en":"Something you cannot stop thinking about.","example":"That catchy jingle is rent-free in my head all day.","example_cn":"那个洗脑的广告曲一整天都在我脑子里转。"},{"id":272,"phrase":"girl math","meaning_cn":"女孩数学（为花钱找有趣的理由）","meaning_en":"Humorous justification for spending decisions.","example":"I returned a $50 item, so this $40 dress is basically free — girl math.","example_cn":"我退了50块的东西，所以这条40块的裙子等于免费——这就是女孩数学。"},{"id":273,"phrase":"delulu is the solulu","meaning_cn":"妄想就是解药（超级自信地相信自己）","meaning_en":"Being delusional is the solution; optimistic self-belief.","example":"I applied for a job way above my level — delulu is the solulu.","example_cn":"我申请了一个远超我水平的职位——妄想就是解药嘛。"},{"id":274,"phrase":"caught the vibe","meaning_cn":"感受到了气氛；融入了氛围","meaning_en":"Successfully understood and matched the mood or atmosphere.","example":"The DJ totally caught the vibe of the crowd tonight.","example_cn":"DJ 今晚完全感受到了观众的氛围。"},{"id":275,"phrase":"have the range","meaning_cn":"多才多艺；什么都能驾驭","meaning_en":"To be versatile and capable of handling many different things.","example":"She can sing, act, and write — she really has the range.","example_cn":"她会唱歌、演戏、写作——她真的很全能。"},{"id":276,"phrase":"put someone on","meaning_cn":"推荐好东西给某人；带人入门","meaning_en":"To introduce someone to something great; recommend.","example":"My friend put me on to this amazing podcast.","example_cn":"我朋友给我推荐了这个超棒的播客。"},{"id":277,"phrase":"the audacity","meaning_cn":"胆子真大；真敢啊","meaning_en":"The shocking nerve or boldness to do something inappropriate.","example":"He showed up two hours late and then complained? The audacity.","example_cn":"他迟到两小时还抱怨？真敢啊。"},{"id":278,"phrase":"do the bare minimum","meaning_cn":"只做最低限度；敷衍了事","meaning_en":"To put in the least amount of effort possible.","example":"He does the bare minimum at work and still expects a raise.","example_cn":"他工作只做最低限度的事，还想加薪。"},{"id":280,"phrase":"a whole mood","meaning_cn":"完全就是我的心情；太有共鸣了","meaning_en":"Something that perfectly captures how you are feeling.","example":"Sitting on the couch in pajamas eating ice cream — a whole mood.","example_cn":"穿着睡衣坐在沙发上吃冰淇淋——完全就是我的心情。"},{"id":281,"phrase":"go off","meaning_cn":"尽情发挥；太厉害了","meaning_en":"To express yourself passionately; to perform impressively.","example":"She really went off during that karaoke session.","example_cn":"她在卡拉OK上真的尽情发挥了。"},{"id":282,"phrase":"big yikes","meaning_cn":"太尴尬了；真的好丢人","meaning_en":"An expression of extreme embarrassment or cringing.","example":"He proposed in public and she said no — big yikes.","example_cn":"他在公共场合求婚被拒了——太尴尬了。"},{"id":283,"phrase":"pick your battles","meaning_cn":"选择性应战；不是每件事都值得争","meaning_en":"Choose which conflicts are worth engaging in.","example":"I know the rules are annoying, but pick your battles.","example_cn":"我知道规则很烦，但不是每件事都值得争。"},{"id":285,"phrase":"the whole nine yards","meaning_cn":"全部；所有的一切","meaning_en":"Everything; the full extent of something.","example":"We decorated the house, cooked a feast — the whole nine yards.","example_cn":"我们装饰了房子、做了大餐——该有的全有了。"},{"id":286,"phrase":"sleep on it","meaning_cn":"先考虑一晚再做决定","meaning_en":"To delay a decision until the next day to think it over.","example":"It is a big investment — why not sleep on it before signing?","example_cn":"这是一笔大投资——签字之前先考虑一晚吧？"},{"id":287,"phrase":"jump the gun","meaning_cn":"操之过急；抢跑","meaning_en":"To start something too soon; act prematurely.","example":"Do not jump the gun — wait for the official announcement.","example_cn":"别操之过急——等官方公告出来再说。"},{"id":292,"phrase":"raise the bar","meaning_cn":"提高标准；树立更高的门槛","meaning_en":"To set higher standards.","example":"Their new product really raised the bar for the industry.","example_cn":"他们的新产品真的给行业树立了更高的标准。"},{"id":298,"phrase":"keep your cool","meaning_cn":"保持冷静；不要慌","meaning_en":"Stay calm and composed under pressure.","example":"Even when the client yelled, she kept her cool and stayed professional.","example_cn":"即使客户大喊大叫，她也保持了冷静和专业。"},{"id":299,"phrase":"out of pocket","meaning_cn":"行为出格；太离谱了（或：自掏腰包）","meaning_en":"Behaving inappropriately or wildly; also: paying from personal funds.","example":"His comment at dinner was completely out of pocket.","example_cn":"他在晚餐上的评论完全出格了。"},{"id":451,"phrase":"let that sink in","meaning_cn":"好好消化一下；让这个消息沉淀一下","meaning_en":"Give yourself time to fully process surprising information.","example":"She earns more than the CEO — let that sink in.","example_cn":"她赚得比CEO还多——好好消化一下吧。"},{"id":452,"phrase":"shots fired","meaning_cn":"火力全开；这话有攻击性啊","meaning_en":"Someone just made a bold or aggressive statement.","example":"She said his cooking was worse than a microwave meal — shots fired.","example_cn":"她说他做的饭比微波炉食品还难吃——这话太狠了。"},{"id":453,"phrase":"im dead","meaning_cn":"笑死我了","meaning_en":"Something is so funny you cannot handle it.","example":"Did you see that meme? I am dead.","example_cn":"你看到那个表情包了吗？我笑死了。"},{"id":454,"phrase":"plot twist","meaning_cn":"剧情反转；意想不到的转折","meaning_en":"An unexpected turn of events.","example":"He was the one who planned the surprise party — plot twist!","example_cn":"原来是他策划的惊喜派对——剧情大反转！"},{"id":455,"phrase":"throw hands","meaning_cn":"打架；准备动手","meaning_en":"To get into a physical fight or be willing to fight.","example":"He insulted my mom and I was ready to throw hands.","example_cn":"他侮辱了我妈妈，我都准备动手了。"},{"id":456,"phrase":"tea","meaning_cn":"八卦；内幕消息","meaning_en":"Gossip or the inside story on something.","example":"What is the tea on why they broke up?","example_cn":"他们分手的内幕是什么？"},{"id":457,"phrase":"not my circus not my monkeys","meaning_cn":"不关我的事；那是别人的烂摊子","meaning_en":"Not my problem or responsibility.","example":"Office drama? Not my circus, not my monkeys.","example_cn":"办公室八卦？不关我的事。"},{"id":458,"phrase":"emotional damage","meaning_cn":"精神伤害；情感暴击","meaning_en":"A humorous way to describe a devastating comeback or insult.","example":"She told him his haircut looked like a lawnmower accident — emotional damage.","example_cn":"她说他的发型像被割草机弄的——精神伤害！"},{"id":1,"phrase":"hit the nail on the head","meaning_cn":"说到点子上；完全说中了","meaning_en":"To be exactly right about something.","example":"You hit the nail on the head — that is exactly the problem.","example_cn":"你说得完全正确——那正是问题所在。"},{"id":2,"phrase":"under the weather","meaning_cn":"身体不舒服；有点生病","meaning_en":"Feeling sick or unwell.","example":"I am feeling under the weather today so I will skip the meeting.","example_cn":"我今天感觉身体不太好，所以要请假不参加会议。"},{"id":3,"phrase":"bite the bullet","meaning_cn":"咬紧牙关；忍痛坚持","meaning_en":"To endure a painful situation with courage.","example":"I just had to bite the bullet and have that difficult conversation.","example_cn":"我只能咬紧牙关，去进行那次艰难的谈话。"},{"id":4,"phrase":"spill the beans","meaning_cn":"说漏嘴；泄露秘密","meaning_en":"To reveal secret information.","example":"Do not spill the beans — it is a surprise party!","example_cn":"别说漏嘴——这是个惊喜派对！"},{"id":5,"phrase":"break the ice","meaning_cn":"打破僵局；打破沉默，开始交流","meaning_en":"To relieve tension and start a conversation.","example":"He told a joke to break the ice at the meeting.","example_cn":"他在会议上讲了个笑话来打破沉默。"},{"id":6,"phrase":"on the fence","meaning_cn":"摇摆不定；举棋不定","meaning_en":"Undecided between two options.","example":"I am still on the fence about accepting the job offer.","example_cn":"对于是否接受这份工作邀请，我仍然举棋不定。"},{"id":7,"phrase":"hit the sack","meaning_cn":"去睡觉；上床休息","meaning_en":"To go to bed and sleep.","example":"I am exhausted — time to hit the sack.","example_cn":"我累坏了——该上床睡觉了。"},{"id":8,"phrase":"costs an arm and a leg","meaning_cn":"价格高得离谱；非常昂贵","meaning_en":"Extremely expensive.","example":"That designer bag costs an arm and a leg.","example_cn":"那个名牌包贵得要命。"},{"id":9,"phrase":"once in a blue moon","meaning_cn":"难得一见；极少发生","meaning_en":"Very rarely.","example":"He calls his parents once in a blue moon.","example_cn":"他难得给父母打一次电话。"},{"id":10,"phrase":"the elephant in the room","meaning_cn":"大家心照不宣却不愿提及的问题","meaning_en":"An obvious problem nobody wants to discuss.","example":"The budget crisis is the elephant in the room at every meeting.","example_cn":"预算危机是每次会议上大家都心知肚明却不愿谈及的问题。"},{"id":11,"phrase":"out of the blue","meaning_cn":"出乎意料地；毫无预兆地","meaning_en":"Unexpectedly with no warning.","example":"She called me out of the blue after five years.","example_cn":"时隔五年，她突然联系了我。"},{"id":12,"phrase":"burn bridges","meaning_cn":"断绝关系；自断后路","meaning_en":"To permanently damage a relationship.","example":"Do not burn bridges when you quit — you might need them again.","example_cn":"辞职时不要把关系弄僵——你以后可能还需要他们。"},{"id":13,"phrase":"beat around the bush","meaning_cn":"拐弯抹角；绕圈子","meaning_en":"To avoid the main topic.","example":"Stop beating around the bush and just tell me the truth.","example_cn":"别绕圈子了，直接告诉我实情吧。"},{"id":14,"phrase":"cut corners","meaning_cn":"偷工减料；图省事","meaning_en":"To do something poorly to save time or money.","example":"They cut corners on construction and the building leaked.","example_cn":"他们在建筑上偷工减料，导致房子漏水。"},{"id":15,"phrase":"hit the books","meaning_cn":"用功读书；认真学习","meaning_en":"To study hard.","example":"I need to hit the books — exams are next week.","example_cn":"我需要好好学习——下周就要考试了。"},{"id":16,"phrase":"let the cat out of the bag","meaning_cn":"不小心泄露秘密；说漏了嘴","meaning_en":"To accidentally reveal a secret.","example":"She let the cat out of the bag about the promotion.","example_cn":"她不小心透露了晋升的消息。"},{"id":17,"phrase":"kill two birds with one stone","meaning_cn":"一举两得；一石二鸟","meaning_en":"To accomplish two things with one action.","example":"I will drop off the package and grab groceries — kill two birds with one stone.","example_cn":"我顺便送包裹再买个菜——一举两得。"},{"id":18,"phrase":"the last straw","meaning_cn":"压垮骆驼的最后一根稻草；忍无可忍的极限","meaning_en":"The final problem that makes a situation unbearable.","example":"His constant lateness was the last straw — she fired him.","example_cn":"他频繁迟到是压垮她忍耐的最后一根稻草——她把他解雇了。"},{"id":19,"phrase":"back to square one","meaning_cn":"回到原点；从头再来","meaning_en":"To start over from the beginning.","example":"The prototype failed so we are back to square one.","example_cn":"原型失败了，我们又得从头开始。"},{"id":20,"phrase":"bite off more than you can chew","meaning_cn":"贪多嚼不烂；揽下超出能力的事","meaning_en":"To take on more than you can handle.","example":"I bit off more than I could chew taking three courses at once.","example_cn":"同时选了三门课，结果我吃不消了。"},{"id":21,"phrase":"a blessing in disguise","meaning_cn":"塞翁失马焉知非福；因祸得福","meaning_en":"Something bad that turns out to be good.","example":"Losing that job was a blessing in disguise — I found a better one.","example_cn":"失去那份工作其实因祸得福——我后来找到了更好的。"},{"id":22,"phrase":"miss the boat","meaning_cn":"错失良机","meaning_en":"To miss an opportunity.","example":"He missed the boat on investing in that startup.","example_cn":"他错过了投资那家初创公司的机会。"},{"id":23,"phrase":"get out of hand","meaning_cn":"失控；变得不可收拾","meaning_en":"To become uncontrollable.","example":"The party got out of hand — neighbors called the police.","example_cn":"派对失控了——邻居打了警察电话。"},{"id":24,"phrase":"on thin ice","meaning_cn":"如履薄冰；处境危险","meaning_en":"In a risky or dangerous situation.","example":"After two warnings he is on thin ice with his boss.","example_cn":"两次警告之后，他和老板的关系岌岌可危。"},{"id":25,"phrase":"pull someone's leg","meaning_cn":"开玩笑；逗人玩","meaning_en":"To joke or tease someone.","example":"Are you serious or just pulling my leg?","example_cn":"你是认真的还是在开我玩笑？"},{"id":26,"phrase":"throw someone under the bus","meaning_cn":"出卖别人以保护自己；甩锅给别人","meaning_en":"To blame someone else to protect yourself.","example":"He threw his coworker under the bus to avoid getting fired.","example_cn":"他为了不被解雇，把同事给出卖了。"},{"id":27,"phrase":"get the ball rolling","meaning_cn":"启动；开始行动","meaning_en":"To start something.","example":"Let us get the ball rolling on this project.","example_cn":"让我们启动这个项目吧。"},{"id":28,"phrase":"in the same boat","meaning_cn":"同舟共济；处境相同","meaning_en":"In the same difficult situation.","example":"We are all in the same boat — nobody knows what to do.","example_cn":"我们都在同一条船上——没有人知道该怎么办。"},{"id":29,"phrase":"take it with a grain of salt","meaning_cn":"将信将疑；不要全信","meaning_en":"To be skeptical about something.","example":"Take his advice with a grain of salt — he exaggerates.","example_cn":"听他的建议时要留个心眼——他爱夸大其词。"},{"id":30,"phrase":"drop the ball","meaning_cn":"失误；搞砸了份内的事","meaning_en":"To make a mistake or fail at something.","example":"I really dropped the ball forgetting that deadline.","example_cn":"我忘了那个截止日期，真的搞砸了。"},{"id":31,"phrase":"up in the air","meaning_cn":"悬而未决；尚不确定","meaning_en":"Uncertain or unresolved.","example":"Our vacation plans are still up in the air.","example_cn":"我们的度假计划还没定下来。"},{"id":32,"phrase":"add fuel to the fire","meaning_cn":"火上浇油；使局势更糟","meaning_en":"To make a bad situation worse.","example":"His sarcastic comment only added fuel to the fire.","example_cn":"他那句讽刺的话只是火上浇油。"},{"id":33,"phrase":"the ball is in your court","meaning_cn":"该你出招了；主动权在你这边","meaning_en":"It is your turn to act.","example":"I have made my offer — the ball is in your court.","example_cn":"我已经出价了——接下来看你的了。"},{"id":34,"phrase":"in hot water","meaning_cn":"处于麻烦之中；惹上麻烦","meaning_en":"In trouble.","example":"He is in hot water with management over that email.","example_cn":"他因为那封邮件在管理层面前惹了麻烦。"},{"id":35,"phrase":"read between the lines","meaning_cn":"揣摩言外之意；理解隐含意思","meaning_en":"To understand the hidden meaning.","example":"Read between the lines — she is not happy about the decision.","example_cn":"从言外之意可以看出——她对这个决定并不满意。"},{"id":36,"phrase":"steal someone's thunder","meaning_cn":"抢走别人的风头；喧宾夺主","meaning_en":"To take attention away from someone.","example":"He announced his news and stole her thunder.","example_cn":"他宣布了自己的消息，把她的风头全抢走了。"},{"id":37,"phrase":"in a nutshell","meaning_cn":"简而言之；总的来说","meaning_en":"In a brief summary.","example":"In a nutshell, we need more funding.","example_cn":"简单来说，我们需要更多资金。"},{"id":38,"phrase":"through thick and thin","meaning_cn":"同甘共苦；无论好坏都在一起","meaning_en":"In all circumstances good and bad.","example":"They have been friends through thick and thin.","example_cn":"他们是同甘共苦的好朋友。"},{"id":39,"phrase":"on a roll","meaning_cn":"接连成功；势头正好","meaning_en":"Experiencing a streak of success.","example":"She is on a roll — three promotions in two years.","example_cn":"她势头正猛——两年内晋升了三次。"},{"id":40,"phrase":"turn a blind eye","meaning_cn":"视而不见；故意忽视","meaning_en":"To ignore something on purpose.","example":"The manager turned a blind eye to the violations.","example_cn":"经理对违规行为视而不见。"},{"id":41,"phrase":"have a lot on your plate","meaning_cn":"事情很多；忙得不可开交","meaning_en":"To be very busy.","example":"I cannot take on more — I have a lot on my plate.","example_cn":"我不能再接更多了——我现在已经焦头烂额了。"},{"id":42,"phrase":"get your ducks in a row","meaning_cn":"把一切安排妥当；做好充分准备","meaning_en":"To organize everything properly.","example":"Get your ducks in a row before the presentation.","example_cn":"演示之前先把一切准备妥当。"},{"id":43,"phrase":"the tip of the iceberg","meaning_cn":"冰山一角；问题只是表面现象","meaning_en":"Only a small visible part of a much larger problem.","example":"Those complaints are just the tip of the iceberg.","example_cn":"那些投诉不过是冰山一角。"},{"id":44,"phrase":"get cold feet","meaning_cn":"临阵退缩；临时打退堂鼓","meaning_en":"To become nervous and hesitant.","example":"She got cold feet right before the wedding.","example_cn":"她在婚礼前夕打了退堂鼓。"},{"id":45,"phrase":"face the music","meaning_cn":"面对后果；接受应有的惩罚","meaning_en":"To accept the consequences of your actions.","example":"He made the mistake — now he has to face the music.","example_cn":"是他犯的错——现在他得承担后果。"},{"id":46,"phrase":"burn the midnight oil","meaning_cn":"开夜车；熬夜工作","meaning_en":"To work very late into the night.","example":"She burned the midnight oil to finish the report.","example_cn":"她熬夜赶完了报告。"},{"id":47,"phrase":"throw in the towel","meaning_cn":"认输；放弃","meaning_en":"To give up.","example":"After three failed attempts he threw in the towel.","example_cn":"三次失败后，他彻底放弃了。"},{"id":48,"phrase":"go the extra mile","meaning_cn":"多付出；超额完成；格外尽心","meaning_en":"To do more than expected.","example":"She always goes the extra mile for her clients.","example_cn":"她对客户总是尽心尽力，超出预期。"},{"id":49,"phrase":"at the drop of a hat","meaning_cn":"立刻；毫不犹豫地","meaning_en":"Immediately and without hesitation.","example":"She would move to Paris at the drop of a hat.","example_cn":"她随时都愿意毫不犹豫地搬去巴黎。"},{"id":50,"phrase":"bark up the wrong tree","meaning_cn":"找错了方向；弄错了对象","meaning_en":"To pursue the wrong course of action.","example":"You are barking up the wrong tree — I did not take it.","example_cn":"你找错人了——东西不是我拿的。"},{"id":51,"phrase":"in the loop","meaning_cn":"了解情况；掌握最新动态","meaning_en":"Kept informed and up to date.","example":"Keep me in the loop about any changes.","example_cn":"有任何变化请及时通知我。"},{"id":52,"phrase":"jump on the bandwagon","meaning_cn":"跟风；随大流","meaning_en":"To follow a trend.","example":"Everyone is jumping on the bandwagon with AI tools.","example_cn":"大家都在跟风使用AI工具。"},{"id":53,"phrase":"neck and neck","meaning_cn":"并驾齐驱；不相上下","meaning_en":"Very close in competition.","example":"The two candidates are neck and neck in the polls.","example_cn":"两位候选人在民调中势均力敌。"},{"id":54,"phrase":"pass the buck","meaning_cn":"推卸责任；甩锅","meaning_en":"To shift responsibility to someone else.","example":"Stop passing the buck — own your mistakes.","example_cn":"别推卸责任了——勇于承担自己的错误。"},{"id":55,"phrase":"hit the ground running","meaning_cn":"迅速投入；全速启动","meaning_en":"To start something quickly with full effort.","example":"The new hire hit the ground running on day one.","example_cn":"新员工第一天就全力以赴地工作了。"},{"id":56,"phrase":"no strings attached","meaning_cn":"没有附加条件；无附带要求","meaning_en":"With no hidden conditions.","example":"The loan comes with no strings attached.","example_cn":"这笔贷款没有任何附加条件。"},{"id":57,"phrase":"over the moon","meaning_cn":"欣喜若狂；高兴极了","meaning_en":"Extremely happy.","example":"She was over the moon about getting into Harvard.","example_cn":"她考上哈佛，高兴得不得了。"},{"id":58,"phrase":"cut to the chase","meaning_cn":"直入主题；说重点","meaning_en":"To get to the point directly.","example":"Cut to the chase — what is the price?","example_cn":"直说吧——价格是多少？"},{"id":59,"phrase":"dodge a bullet","meaning_cn":"侥幸逃过一劫","meaning_en":"To narrowly avoid something bad.","example":"We dodged a bullet — the deal fell through before we lost money.","example_cn":"我们真是幸运——那笔交易在亏损前就告吹了。"},{"id":60,"phrase":"put all your eggs in one basket","meaning_cn":"孤注一掷；把所有赌注押在一件事上","meaning_en":"To risk everything on one option.","example":"Do not put all your eggs in one basket — diversify.","example_cn":"别把所有鸡蛋放在一个篮子里——要分散风险。"},{"id":61,"phrase":"sell like hotcakes","meaning_cn":"供不应求；畅销热卖","meaning_en":"To sell very quickly in large quantities.","example":"The new phone model sold like hotcakes.","example_cn":"新款手机一上市就抢购一空。"},{"id":62,"phrase":"make ends meet","meaning_cn":"勉强维持生计；收支相抵","meaning_en":"To have just enough money to survive.","example":"With two jobs she can barely make ends meet.","example_cn":"打两份工她也只是勉强够用。"},{"id":63,"phrase":"see eye to eye","meaning_cn":"看法一致；意见相同","meaning_en":"To agree on something.","example":"We do not always see eye to eye but we respect each other.","example_cn":"我们不总是意见一致，但互相尊重。"},{"id":64,"phrase":"in the nick of time","meaning_cn":"千钧一发；在最后关头","meaning_en":"Just in time at the last possible moment.","example":"The ambulance arrived in the nick of time.","example_cn":"救护车在最后关头赶到了。"},{"id":65,"phrase":"bite the dust","meaning_cn":"以失败告终；倒下","meaning_en":"To fail or end.","example":"Another startup bites the dust.","example_cn":"又一家创业公司倒闭了。"},{"id":66,"phrase":"show your true colors","meaning_cn":"原形毕露；显露本来面目","meaning_en":"To reveal your real character.","example":"He showed his true colors after the promotion.","example_cn":"晋升之后他才显露了本来面目。"},{"id":67,"phrase":"take the bull by the horns","meaning_cn":"迎难而上；主动面对挑战","meaning_en":"To confront a problem directly.","example":"She took the bull by the horns and confronted her boss.","example_cn":"她鼓起勇气，直接去找老板谈了。"},{"id":68,"phrase":"under someone's thumb","meaning_cn":"受人控制；任人摆布","meaning_en":"Controlled by someone.","example":"He has been under his boss's thumb for years.","example_cn":"多年来他一直在老板的掌控之下。"},{"id":69,"phrase":"water under the bridge","meaning_cn":"往事已矣；翻篇了","meaning_en":"Past events that are over and forgotten.","example":"The argument happened years ago — water under the bridge.","example_cn":"那次争吵是多年前的事了——翻篇吧。"},{"id":70,"phrase":"when pigs fly","meaning_cn":"除非太阳从西边出来；绝无可能","meaning_en":"Something that will never happen.","example":"He will apologize when pigs fly.","example_cn":"他道歉？那除非太阳从西边出来。"},{"id":71,"phrase":"blow off steam","meaning_cn":"发泄情绪；释放压力","meaning_en":"To release frustration or stress.","example":"He goes running to blow off steam.","example_cn":"他通过跑步来发泄情绪。"},{"id":72,"phrase":"break even","meaning_cn":"收支平衡；不赚不亏","meaning_en":"To have no profit or loss.","example":"After expenses the event just broke even.","example_cn":"扣除开支后，这次活动仅仅持平。"},{"id":73,"phrase":"run out of steam","meaning_cn":"后劲不足；精力耗尽","meaning_en":"To lose energy or motivation.","example":"The project ran out of steam halfway through.","example_cn":"这个项目做到一半就没了动力。"},{"id":74,"phrase":"stir the pot","meaning_cn":"故意制造麻烦；惹事生非","meaning_en":"To cause trouble or drama intentionally.","example":"She loves stirring the pot at family dinners.","example_cn":"她喜欢在家庭聚会上煽风点火。"},{"id":75,"phrase":"speak of the devil","meaning_cn":"说曹操，曹操就到","meaning_en":"Said when someone appears just as you mention them.","example":"Speak of the devil — here comes Sarah now.","example_cn":"说曹操，曹操就到——莎拉来了。"},{"id":76,"phrase":"weather the storm","meaning_cn":"熬过艰难时期；渡过难关","meaning_en":"To survive a difficult period.","example":"The company weathered the storm of the recession.","example_cn":"公司熬过了经济衰退的考验。"},{"id":77,"phrase":"let sleeping dogs lie","meaning_cn":"别没事找事；不要重提旧事","meaning_en":"To avoid bringing up old problems.","example":"Do not mention the lawsuit — let sleeping dogs lie.","example_cn":"别提那场官司了——别没事找事。"},{"id":78,"phrase":"give the benefit of the doubt","meaning_cn":"善意地对待；宽容看待","meaning_en":"To trust someone despite uncertainty.","example":"She is new — give her the benefit of the doubt.","example_cn":"她是新来的——给她一个机会。"},{"id":79,"phrase":"take the cake","meaning_cn":"登峰造极；令人叹为观止（通常指不好的事）","meaning_en":"To be the most extreme example.","example":"That excuse really takes the cake.","example_cn":"那个借口真是绝了。"},{"id":80,"phrase":"miss the point","meaning_cn":"没理解要点；误解了意思","meaning_en":"To fail to understand the main idea.","example":"He completely missed the point of her feedback.","example_cn":"他完全没明白她反馈的意思。"},{"id":81,"phrase":"keep your chin up","meaning_cn":"振作精神；保持乐观","meaning_en":"To stay positive in a difficult situation.","example":"Keep your chin up — things will improve.","example_cn":"振作起来——事情会好转的。"},{"id":82,"phrase":"cost a fortune","meaning_cn":"花费巨大；非常昂贵","meaning_en":"To be very expensive.","example":"Renovating the kitchen cost a fortune.","example_cn":"厨房装修花了一大笔钱。"},{"id":83,"phrase":"have the upper hand","meaning_cn":"占有优势；处于主动地位","meaning_en":"To be in a position of advantage.","example":"With more data we will have the upper hand in negotiations.","example_cn":"掌握更多数据后，我们在谈判中将占据优势。"},{"id":84,"phrase":"think on your feet","meaning_cn":"随机应变；临场灵活应对","meaning_en":"To make quick decisions without preparation.","example":"Good teachers can think on their feet.","example_cn":"优秀的教师能够随机应变。"},{"id":85,"phrase":"drive someone up the wall","meaning_cn":"让人烦透了；气得不行","meaning_en":"To irritate or annoy someone greatly.","example":"That constant tapping is driving me up the wall.","example_cn":"那不停的敲击声快把我逼疯了。"},{"id":86,"phrase":"go back to the drawing board","meaning_cn":"推倒重来；重新设计","meaning_en":"To start a plan over from scratch.","example":"The client rejected it — back to the drawing board.","example_cn":"客户否定了方案——只好重头再来。"},{"id":87,"phrase":"under wraps","meaning_cn":"保密；未公开","meaning_en":"Kept secret.","example":"The new product is still under wraps.","example_cn":"新产品目前还处于保密阶段。"},{"id":88,"phrase":"no pain no gain","meaning_cn":"一分耕耘，一分收获；没有付出就没有收获","meaning_en":"You must work hard to get results.","example":"I hate the gym but no pain no gain.","example_cn":"我不喜欢去健身房，但没有付出就没有收获。"},{"id":89,"phrase":"push the envelope","meaning_cn":"突破极限；大胆创新","meaning_en":"To go beyond normal limits.","example":"This design really pushes the envelope.","example_cn":"这个设计真的突破了常规。"},{"id":90,"phrase":"have an ace up your sleeve","meaning_cn":"留有后手；暗藏杀手锏","meaning_en":"To have a hidden advantage.","example":"She has an ace up her sleeve in the negotiation.","example_cn":"在谈判中她还藏着一张底牌。"},{"id":91,"phrase":"wrap your head around","meaning_cn":"理解（某件复杂的事）；弄懂","meaning_en":"To understand something complex.","example":"I cannot wrap my head around quantum physics.","example_cn":"量子物理我实在想不明白。"},{"id":92,"phrase":"at the end of your rope","meaning_cn":"忍无可忍；精疲力竭到了极限","meaning_en":"At the limit of your patience.","example":"After six hours of delays I was at the end of my rope.","example_cn":"经历了六个小时的延误后，我已经到了崩溃边缘。"},{"id":93,"phrase":"strike while the iron is hot","meaning_cn":"趁热打铁；抓住时机","meaning_en":"To act at the best opportunity.","example":"Submit the application now — strike while the iron is hot.","example_cn":"现在就提交申请——要趁热打铁。"},{"id":94,"phrase":"pull strings","meaning_cn":"走后门；动用人脉","meaning_en":"To use influence to get something done.","example":"His father pulled strings to get him the internship.","example_cn":"他父亲动用关系帮他拿到了这份实习。"},{"id":95,"phrase":"get a taste of your own medicine","meaning_cn":"自食其果；以其人之道还治其人之身","meaning_en":"To experience what you have done to others.","example":"He finally got a taste of his own medicine.","example_cn":"他终于尝到了自己种的苦果。"},{"id":96,"phrase":"straight from the horse's mouth","meaning_cn":"直接从当事人那里听到；来自最权威的来源","meaning_en":"Directly from the original source.","example":"I heard it straight from the horse's mouth.","example_cn":"这消息我是直接从当事人口中听到的。"},{"id":97,"phrase":"tie the knot","meaning_cn":"喜结连理；结婚","meaning_en":"To get married.","example":"They are tying the knot in June.","example_cn":"他们六月份要结婚了。"},{"id":98,"phrase":"vanish into thin air","meaning_cn":"凭空消失；无影无踪","meaning_en":"To disappear completely.","example":"The money just vanished into thin air.","example_cn":"那笔钱就这样不翼而飞了。"},{"id":99,"phrase":"you cannot have your cake and eat it too","meaning_cn":"鱼与熊掌不可兼得","meaning_en":"You cannot have everything at once.","example":"You cannot have your cake and eat it too — choose one.","example_cn":"鱼与熊掌不可兼得——选一个吧。"},{"id":100,"phrase":"pull it off","meaning_cn":"成功做到；做成了难事","meaning_en":"To succeed at something difficult.","example":"I did not think we could do it but we pulled it off.","example_cn":"我以为我们做不到，但我们成功了。"},{"id":481,"phrase":"behind closed doors","meaning_cn":"私下里；暗中进行（非公开）","meaning_en":"In private, away from public view.","example":"The real decisions were made behind closed doors.","example_cn":"真正的决定是在私下里做出的。"},{"id":482,"phrase":"smoking gun","meaning_cn":"铁证；无可辩驳的证据","meaning_en":"Clear, undeniable evidence of guilt or wrongdoing.","example":"The emails were the smoking gun prosecutors needed.","example_cn":"这些邮件正是检察官需要的铁证。"},{"id":483,"phrase":"sweep under the rug","meaning_cn":"掩盖问题；息事宁人","meaning_en":"To hide or ignore a problem instead of addressing it.","example":"The company tried to sweep the scandal under the rug.","example_cn":"公司试图把丑闻掩盖过去。"},{"id":484,"phrase":"double-edged sword","meaning_cn":"双刃剑；好坏参半的事物","meaning_en":"Something that has both positive and negative consequences.","example":"Social media is a double-edged sword for teenagers.","example_cn":"社交媒体对青少年来说是一把双刃剑。"},{"id":485,"phrase":"cross the line","meaning_cn":"越界；做得太过分","meaning_en":"To go beyond what is acceptable or allowed.","example":"Joking about her family really crossed the line.","example_cn":"拿她家人开玩笑真的太过分了。"},{"id":486,"phrase":"in the hot seat","meaning_cn":"处于风口浪尖；被追问的处境","meaning_en":"Under intense pressure or scrutiny, especially for questioning.","example":"The CEO was in the hot seat at yesterday's hearing.","example_cn":"昨天的听证会上，首席执行官处于风口浪尖。"},{"id":487,"phrase":"rubber stamp","meaning_cn":"走过场式批准；橡皮图章式通过","meaning_en":"To approve something without real review or questioning.","example":"The board simply rubber-stamped the CEO's proposal.","example_cn":"董事会只是走过场式地批准了CEO的提案。"},{"id":488,"phrase":"lame duck","meaning_cn":"跛脚鸭（任期将满、实权下降的官员）","meaning_en":"An official nearing the end of their term with reduced power.","example":"The lame duck president signed few new laws.","example_cn":"这位跛脚鸭总统签署的新法律寥寥无几。"},{"id":489,"phrase":"take the heat","meaning_cn":"替人扛责；承受指责","meaning_en":"To accept blame or criticism for something.","example":"He took the heat for the team's mistakes.","example_cn":"他为团队的错误承担了责任。"},{"id":490,"phrase":"call the shots","meaning_cn":"发号施令；做主","meaning_en":"To make the decisions; to be in charge.","example":"In this office, she really calls the shots.","example_cn":"在这间办公室里，真正做主的是她。"},{"id":491,"phrase":"play hardball","meaning_cn":"玩硬的；采取强硬手段","meaning_en":"To act aggressively and without compromise.","example":"The union decided to play hardball in negotiations.","example_cn":"工会决定在谈判中采取强硬立场。"},{"id":492,"phrase":"skin in the game","meaning_cn":"有切身利益；亲自下场承担风险","meaning_en":"Having personal risk or investment in an outcome.","example":"Investors want founders to have skin in the game.","example_cn":"投资人希望创始人有切身利益的绑定。"},{"id":493,"phrase":"ruffle feathers","meaning_cn":"惹人不快；招致反感","meaning_en":"To upset or annoy people.","example":"His blunt remarks ruffled some feathers at the meeting.","example_cn":"他直率的话在会上让一些人不太高兴。"},{"id":494,"phrase":"drag your feet","meaning_cn":"拖拖拉拉；故意拖延","meaning_en":"To delay or act reluctantly.","example":"Congress is dragging its feet on the new bill.","example_cn":"国会在新法案上拖拖拉拉。"},{"id":495,"phrase":"walk on eggshells","meaning_cn":"小心翼翼；如履薄冰","meaning_en":"To act carefully to avoid upsetting someone.","example":"Since the fight, I've been walking on eggshells around her.","example_cn":"自从那次争吵后，我跟她相处都小心翼翼。"},{"id":496,"phrase":"cross that bridge when you come to it","meaning_cn":"船到桥头自然直；到时候再说","meaning_en":"Deal with a problem only when it arises.","example":"Will we need a bigger office? We'll cross that bridge when we come to it.","example_cn":"我们需要更大的办公室吗？到时候再说吧。"},{"id":497,"phrase":"know the ropes","meaning_cn":"熟悉门道；摸清规则","meaning_en":"To be familiar with how something works.","example":"After a year here, she really knows the ropes.","example_cn":"在这里工作一年后，她已经完全熟悉业务了。"},{"id":498,"phrase":"throw a wrench in it","meaning_cn":"从中作梗；搅局","meaning_en":"To ruin plans or disrupt progress.","example":"The delayed flight threw a wrench in our itinerary.","example_cn":"航班延误打乱了我们的行程。"},{"id":499,"phrase":"up for grabs","meaning_cn":"谁有本事谁拿；尚无归属","meaning_en":"Available for anyone to win or take.","example":"The championship title is up for grabs this year.","example_cn":"今年的冠军宝座花落谁家还未可知。"},{"id":500,"phrase":"a tall order","meaning_cn":"艰巨的任务；苛刻的要求","meaning_en":"A difficult task or challenging demand.","example":"Finishing this report by tomorrow is a tall order.","example_cn":"明天之前完成这份报告是个艰巨的任务。"},{"id":501,"phrase":"cash cow","meaning_cn":"摇钱树；稳赚不赔的业务","meaning_en":"A product or business generating steady profits.","example":"That franchise has become a real cash cow for the studio.","example_cn":"这个系列已成为片厂的一棵摇钱树。"},{"id":502,"phrase":"the tide is turning","meaning_cn":"风向变了；形势在扭转","meaning_en":"The situation is changing direction.","example":"Polls suggest the tide is turning against the incumbent.","example_cn":"民调显示形势正不利于现任者。"},{"id":503,"phrase":"pull the plug","meaning_cn":"叫停；终止","meaning_en":"To end something abruptly.","example":"The network decided to pull the plug on the show.","example_cn":"电视台决定停播这个节目。"},{"id":504,"phrase":"the jig is up","meaning_cn":"把戏被识破了；事情败露","meaning_en":"The trick or deception is exposed.","example":"When they found the fake passport, the jig was up.","example_cn":"他们发现假护照后，把戏就败露了。"},{"id":505,"phrase":"play your cards right","meaning_cn":"出牌得当；处理得当","meaning_en":"To act wisely and strategically.","example":"If you play your cards right, this job will open doors.","example_cn":"如果你处理得当，这份工作会为你开启很多机会。"},{"id":506,"phrase":"keep your powder dry","meaning_cn":"养精蓄锐；保持待命","meaning_en":"To stay prepared and wait for the right moment.","example":"For now, keep your powder dry — the time will come.","example_cn":"眼下先养精蓄锐，时机终会到来。"},{"id":507,"phrase":"hold your fire","meaning_cn":"先别开火；暂且按兵不动","meaning_en":"To wait before acting or criticizing.","example":"Hold your fire — let's hear his side first.","example_cn":"先别急着指责——让我们先听听他的说法。"},{"id":508,"phrase":"in the crosshairs","meaning_cn":"被盯上了；成为众矢之的","meaning_en":"Targeted for attack or criticism.","example":"The company is now in the crosshairs of regulators.","example_cn":"这家公司如今成了监管机构的重点对象。"},{"id":509,"phrase":"blow the whistle","meaning_cn":"吹哨揭发；举报","meaning_en":"To expose wrongdoing publicly.","example":"She blew the whistle on corporate fraud.","example_cn":"她举报了公司的欺诈行为。"},{"id":510,"phrase":"hang in the balance","meaning_cn":"悬而未决；命悬一线","meaning_en":"In an uncertain, precarious state.","example":"Millions of jobs hang in the balance of the vote.","example_cn":"数百万人的工作悬于这次投票之上。"},{"id":511,"phrase":"come to a head","meaning_cn":"发展到关键节点；到了摊牌时刻","meaning_en":"To reach a critical point.","example":"Tensions finally came to a head at the meeting.","example_cn":"紧张局势最终在会议上爆发。"},{"id":512,"phrase":"under the radar","meaning_cn":"低调行事；不引人注意","meaning_en":"Avoiding notice; low-profile.","example":"The startup grew under the radar for years.","example_cn":"这家初创公司多年来一直低调发展。"},{"id":513,"phrase":"fly off the handle","meaning_cn":"勃然大怒；突然爆发","meaning_en":"To suddenly lose one's temper.","example":"He flew off the handle when he saw the bill.","example_cn":"他一看到账单就勃然大怒。"},{"id":514,"phrase":"read the riot act","meaning_cn":"严厉训斥；下最后通牒","meaning_en":"To strictly scold or warn someone.","example":"The coach read them the riot act after the loss.","example_cn":"教练在失利后把他们狠狠训了一顿。"},{"id":515,"phrase":"stick to your guns","meaning_cn":"坚持立场；不改口","meaning_en":"To refuse to change your position.","example":"Even under pressure, she stuck to her guns.","example_cn":"即使在压力下，她仍坚持自己的立场。"},{"id":516,"phrase":"toe the line","meaning_cn":"守规矩；遵守路线","meaning_en":"To follow rules or orders strictly.","example":"New employees are expected to toe the line.","example_cn":"新员工被要求严格遵守规矩。"},{"id":517,"phrase":"have your hands tied","meaning_cn":"爱莫能助；被束缚","meaning_en":"To be unable to act due to restrictions.","example":"I'd love to help, but my hands are tied.","example_cn":"我也想帮忙，但实在爱莫能助。"},{"id":518,"phrase":"move the goalposts","meaning_cn":"临时改规则；移动目标","meaning_en":"To unfairly change the rules mid-game.","example":"They keep moving the goalposts on what counts as success.","example_cn":"他们不断改变成功的标准。"},{"id":519,"phrase":"flip the script","meaning_cn":"反转剧情；翻转局面","meaning_en":"To reverse the expected situation.","example":"The underdog flipped the script in the final inning.","example_cn":"黑马在最后一局完成了惊天逆转。"},{"id":520,"phrase":"be in someone's corner","meaning_cn":"力挺某人；在某人那边","meaning_en":"To strongly support someone.","example":"No matter what, I'm in your corner.","example_cn":"无论发生什么，我都支持你。"},{"id":521,"phrase":"ballpark figure","meaning_cn":"大致数字；粗略估算","meaning_en":"A rough estimate.","example":"Give me a ballpark figure for the budget.","example_cn":"给我一个大致的预算数字。"},{"id":522,"phrase":"the bottom line","meaning_cn":"底线；最关键的点","meaning_en":"The most important point; the final result.","example":"The bottom line is we need to cut costs.","example_cn":"最关键的一点是我们得降低成本。"},{"id":523,"phrase":"cutting edge","meaning_cn":"最前沿；尖端","meaning_en":"The most advanced level of something.","example":"Their research is on the cutting edge of AI.","example_cn":"他们的研究处于人工智能的最前沿。"},{"id":524,"phrase":"break new ground","meaning_cn":"开辟新领域；做前人未做的事","meaning_en":"To do something innovative.","example":"Her book breaks new ground in feminist theory.","example_cn":"她的书在女性主义理论上开辟了新领域。"},{"id":525,"phrase":"a drop in the bucket","meaning_cn":"九牛一毛；杯水车薪","meaning_en":"A tiny, insignificant amount.","example":"A million dollars is a drop in the bucket for them.","example_cn":"一百万对他们来说不过九牛一毛。"},{"id":526,"phrase":"across the board","meaning_cn":"全面地；一概而论","meaning_en":"Affecting everyone or everything equally.","example":"The company raised salaries across the board.","example_cn":"公司给所有员工普涨了工资。"},{"id":527,"phrase":"crunch the numbers","meaning_cn":"仔细算一算；分析数据","meaning_en":"To analyze data or calculations.","example":"Let me crunch the numbers before I answer.","example_cn":"让我仔细算一算再回答你。"},{"id":528,"phrase":"in the red","meaning_cn":"亏损；赤字","meaning_en":"Operating at a loss; in debt.","example":"The company has been in the red for two quarters.","example_cn":"公司已经连续两个季度亏损。"},{"id":529,"phrase":"in the black","meaning_cn":"盈利；有利润","meaning_en":"Profitable; not in debt.","example":"Thanks to holiday sales we're in the black again.","example_cn":"多亏了假日销售，我们又开始盈利了。"},{"id":530,"phrase":"lose your shirt","meaning_cn":"输光了；亏得底裤都不剩","meaning_en":"To lose all your money.","example":"He lost his shirt in the crypto crash.","example_cn":"他在加密货币崩盘中亏得一塌糊涂。"},{"id":531,"phrase":"make a killing","meaning_cn":"大赚一笔；狠捞一把","meaning_en":"To earn a lot of money quickly.","example":"They made a killing selling the land.","example_cn":"他们卖地狠狠赚了一笔。"},{"id":532,"phrase":"pay through the nose","meaning_cn":"付高价；被宰","meaning_en":"To pay an excessive amount.","example":"We paid through the nose for courtside seats.","example_cn":"我们为场边座位付了天价。"},{"id":533,"phrase":"shell out","meaning_cn":"掏钱；花大钱","meaning_en":"To pay (usually a large amount).","example":"I had to shell out $500 for those shoes.","example_cn":"我不得不花500美元买了那双鞋。"},{"id":534,"phrase":"tighten your belt","meaning_cn":"勒紧裤腰带；节衣缩食","meaning_en":"To spend less money.","example":"Everyone is tightening their belts this quarter.","example_cn":"大家这个季度都在精打细算。"},{"id":535,"phrase":"foot the bill","meaning_cn":"买单；承担费用","meaning_en":"To pay for something.","example":"The company footed the bill for the retreat.","example_cn":"公司承担了团建的费用。"},{"id":536,"phrase":"money talks","meaning_cn":"钱能使鬼推磨；钱说了算","meaning_en":"Money has the power to persuade.","example":"In this town, money talks — and loudly.","example_cn":"在这个地方，钱说话最大声。"},{"id":537,"phrase":"nest egg","meaning_cn":"养老金；私房钱","meaning_en":"Savings for the future.","example":"They built up a nice nest egg for retirement.","example_cn":"他们为退休存了一笔可观的养老金。"},{"id":538,"phrase":"cash in","meaning_cn":"趁机捞钱；套现","meaning_en":"To profit from an opportunity.","example":"He cashed in on the crypto boom.","example_cn":"他趁加密货币热潮狠狠捞了一笔。"},{"id":539,"phrase":"corner the market","meaning_cn":"垄断市场；独占鳌头","meaning_en":"To dominate a market.","example":"Apple has cornered the market on premium phones.","example_cn":"苹果几乎垄断了高端手机市场。"},{"id":540,"phrase":"gravy train","meaning_cn":"躺着赚钱的好差事","meaning_en":"An easy source of steady income.","example":"That book deal was a real gravy train.","example_cn":"那份出书合同简直是躺着数钱。"},{"id":541,"phrase":"the lion's share","meaning_cn":"最大的一份；大头","meaning_en":"The largest portion.","example":"She took the lion's share of the profits.","example_cn":"她拿走了利润的大头。"},{"id":542,"phrase":"sign on the dotted line","meaning_cn":"签字确认；正式承诺","meaning_en":"To formally commit to something.","example":"Don't sign on the dotted line until you read the fine print.","example_cn":"在看清细则之前，不要贸然签字。"},{"id":543,"phrase":"in full swing","meaning_cn":"正在热烈进行中；如火如荼","meaning_en":"In its most active phase.","example":"The festival was in full swing by sunset.","example_cn":"到日落时节日已经进入高潮。"},{"id":544,"phrase":"write off","meaning_cn":"一笔勾销；认为没戏","meaning_en":"To dismiss as worthless.","example":"Don't write off the underdog just yet.","example_cn":"先别急着否定这匹黑马。"},{"id":545,"phrase":"on the hook","meaning_cn":"要扛责；脱不了干系","meaning_en":"Responsible for something.","example":"If this fails, we're all on the hook.","example_cn":"如果搞砸了，我们都难辞其咎。"},{"id":546,"phrase":"Monday morning quarterback","meaning_cn":"事后诸葛亮","meaning_en":"Someone who criticizes with hindsight.","example":"Don't be a Monday morning quarterback — that play made sense at the time.","example_cn":"别做事后诸葛亮，那个战术当时是合理的。"},{"id":547,"phrase":"out of left field","meaning_cn":"出其不意；来得突然","meaning_en":"Unexpected or strange.","example":"His resignation came out of left field.","example_cn":"他的辞职令人意外。"},{"id":548,"phrase":"slam dunk","meaning_cn":"十拿九稳的事；轻松搞定","meaning_en":"An easy, certain success.","example":"Winning that contract was a slam dunk.","example_cn":"拿下那份合同是十拿九稳的事。"},{"id":549,"phrase":"knock it out of the park","meaning_cn":"一炮打响；大获成功","meaning_en":"To succeed impressively.","example":"Her speech knocked it out of the park.","example_cn":"她的演讲大获成功。"},{"id":550,"phrase":"full-court press","meaning_cn":"全线施压；全面紧逼","meaning_en":"Intense, all-out pressure.","example":"The media put on a full-court press for interviews.","example_cn":"媒体全面出动来争取采访。"},{"id":551,"phrase":"on the ropes","meaning_cn":"濒临失败；岌岌可危","meaning_en":"On the verge of defeat.","example":"The business is on the ropes after the lawsuit.","example_cn":"官司之后这家公司岌岌可危。"},{"id":552,"phrase":"down for the count","meaning_cn":"被击倒；暂时起不来","meaning_en":"Defeated; unable to recover immediately.","example":"After that flop, he was down for the count.","example_cn":"经历那次失败后，他一蹶不振。"},{"id":553,"phrase":"saved by the bell","meaning_cn":"最后关头被救；险些遭殃","meaning_en":"Rescued at the last moment.","example":"I didn't know the answer, but was saved by the bell.","example_cn":"我不知道答案，幸好下课铃响了。"},{"id":554,"phrase":"below the belt","meaning_cn":"下三滥；打人不打脸","meaning_en":"Unfairly personal or low-blow.","example":"Mocking his accent was below the belt.","example_cn":"嘲笑他的口音太过分了。"},{"id":555,"phrase":"throw a curveball","meaning_cn":"出其不意；冷不丁来一手","meaning_en":"To present something unexpected.","example":"The interviewer threw me a curveball.","example_cn":"面试官冷不防问了我一个刁钻的问题。"},{"id":556,"phrase":"touch and go","meaning_cn":"险象环生；岌岌可危","meaning_en":"Very uncertain or risky.","example":"The surgery was touch and go for hours.","example_cn":"手术在几个小时里都岌岌可危。"},{"id":557,"phrase":"the home stretch","meaning_cn":"最后冲刺阶段","meaning_en":"The final part of a journey or task.","example":"Just one more chapter — we're in the home stretch.","example_cn":"只剩一章了——我们已经到了最后冲刺阶段。"},{"id":558,"phrase":"Hail Mary","meaning_cn":"孤注一掷；绝地一搏","meaning_en":"A desperate last-chance attempt.","example":"Their third-quarter pitch was a Hail Mary.","example_cn":"他们第三季度的提案是一场孤注一掷。"},{"id":559,"phrase":"photo finish","meaning_cn":"终点一瞬；难分伯仲","meaning_en":"An extremely close finish.","example":"The election was a photo finish.","example_cn":"这次选举势均力敌，胜负难分。"},{"id":560,"phrase":"play ball","meaning_cn":"开场；配合一下","meaning_en":"To cooperate or get started.","example":"If they play ball, the deal closes tonight.","example_cn":"只要他们配合，今晚就能签约。"},{"id":561,"phrase":"second wind","meaning_cn":"重振精神；恢复体力","meaning_en":"Renewed energy after being tired.","example":"After coffee she got her second wind.","example_cn":"喝完咖啡她又来了精神。"},{"id":562,"phrase":"hit your stride","meaning_cn":"渐入佳境；进入状态","meaning_en":"To reach a comfortable, steady pace.","example":"By week three, she'd hit her stride.","example_cn":"到了第三周，她已经完全进入状态。"},{"id":563,"phrase":"in the ballpark","meaning_cn":"接近；八九不离十","meaning_en":"Approximately correct.","example":"Your estimate is in the ballpark.","example_cn":"你的估算已经八九不离十。"},{"id":564,"phrase":"step up to the plate","meaning_cn":"挺身而出；担起重任","meaning_en":"To take responsibility or action.","example":"It's time to step up to the plate and lead.","example_cn":"是时候挺身而出、担起领导重任了。"},{"id":565,"phrase":"the gloves are off","meaning_cn":"撕破脸；动真格的了","meaning_en":"The nice approach is over; things get rough.","example":"Once he insulted her family, the gloves were off.","example_cn":"一旦他侮辱了她的家人，她就不再客气。"},{"id":566,"phrase":"steal the show","meaning_cn":"抢尽风头；成为全场焦点","meaning_en":"To attract more attention than anyone else.","example":"The child actor stole the show.","example_cn":"小演员抢尽了风头。"},{"id":567,"phrase":"behind the scenes","meaning_cn":"幕后；不公开的","meaning_en":"Not visible to the public; working privately.","example":"A lot happens behind the scenes in film production.","example_cn":"电影制作有很多幕后工作。"},{"id":568,"phrase":"make a scene","meaning_cn":"当众发作；大吵大闹","meaning_en":"To cause a public commotion.","example":"Please don't make a scene at the restaurant.","example_cn":"请别在餐厅当众发作。"},{"id":569,"phrase":"drop a bombshell","meaning_cn":"爆出猛料；扔下一颗炸弹","meaning_en":"To announce shocking news.","example":"She dropped a bombshell at the meeting.","example_cn":"她在会上爆出了猛料。"},{"id":570,"phrase":"in the spotlight","meaning_cn":"受关注；聚光灯下","meaning_en":"Receiving public attention.","example":"The CEO has been in the spotlight all week.","example_cn":"首席执行官本周一直处于舆论聚焦之下。"},{"id":571,"phrase":"roll with the punches","meaning_cn":"随机应变；从容应对","meaning_en":"To adapt to difficulties calmly.","example":"She learned to roll with the punches in fast-paced news.","example_cn":"她学会了在快节奏新闻中随机应变。"},{"id":572,"phrase":"rain on someone's parade","meaning_cn":"扫兴；搅局","meaning_en":"To spoil someone's happy moment.","example":"I hate to rain on your parade, but we can't afford it.","example_cn":"我不想扫你兴，但我们负担不起。"},{"id":573,"phrase":"pull out all the stops","meaning_cn":"使出浑身解数；不遗余力","meaning_en":"To make every possible effort.","example":"The team pulled out all the stops for the launch.","example_cn":"团队为产品发布倾尽了全力。"},{"id":574,"phrase":"wait in the wings","meaning_cn":"候场；随时准备上场","meaning_en":"To be ready for an opportunity.","example":"Her understudy was waiting in the wings.","example_cn":"她的替补演员正在候场。"},{"id":575,"phrase":"jump the shark","meaning_cn":"走下坡路；过气","meaning_en":"To go past the peak of quality.","example":"The show jumped the shark in season seven.","example_cn":"那部剧第七季开始走下坡路。"},{"id":576,"phrase":"strike a chord","meaning_cn":"引起共鸣；触动心弦","meaning_en":"To evoke strong feelings.","example":"Her speech struck a chord with young voters.","example_cn":"她的演讲引起了年轻选民的共鸣。"},{"id":577,"phrase":"hit the big time","meaning_cn":"大红大紫；一炮走红","meaning_en":"To achieve major success.","example":"After that movie she really hit the big time.","example_cn":"那部电影之后她真的大红大紫了。"},{"id":578,"phrase":"flash in the pan","meaning_cn":"昙花一现；短暂走红","meaning_en":"A brief success that doesn't last.","example":"That singer was just a flash in the pan.","example_cn":"那位歌手只是昙花一现。"},{"id":579,"phrase":"front and center","meaning_cn":"正前方；最显眼的位置","meaning_en":"In a prominent position.","example":"Diversity is front and center in their new campaign.","example_cn":"多元化是他们新活动的核心重点。"},{"id":580,"phrase":"wear many hats","meaning_cn":"身兼数职；一人多岗","meaning_en":"To have multiple roles or jobs.","example":"In a startup you wear many hats.","example_cn":"在初创公司，你要身兼数职。"},{"id":581,"phrase":"play second fiddle","meaning_cn":"当陪衬；处于次要位置","meaning_en":"To take a less important role.","example":"He refused to play second fiddle to his colleague.","example_cn":"他不愿意当同事的陪衬。"},{"id":582,"phrase":"set the stage","meaning_cn":"铺垫；为…作准备","meaning_en":"To prepare for something to happen.","example":"The meeting set the stage for a major deal.","example_cn":"这次会议为一笔大交易做了铺垫。"},{"id":583,"phrase":"steal the thunder","meaning_cn":"抢了某人的风头；夺走荣耀","meaning_en":"To take attention or credit from someone.","example":"Don't let them steal your thunder — you did the work.","example_cn":"别让他们抢了你的风头——是你干的活。"},{"id":584,"phrase":"take center stage","meaning_cn":"成为焦点；占据中心位置","meaning_en":"To become the main focus.","example":"Climate change has taken center stage in politics.","example_cn":"气候变化已成为政界焦点。"},{"id":585,"phrase":"break a leg","meaning_cn":"祝你好运（尤指演出前）","meaning_en":"Good luck! (especially before performances)","example":"Break a leg at the audition tonight!","example_cn":"祝你今晚试镜顺利！"},{"id":586,"phrase":"a piece of cake","meaning_cn":"小菜一碟；轻而易举","meaning_en":"Very easy.","example":"For her, calculus is a piece of cake.","example_cn":"对她来说，微积分小菜一碟。"},{"id":587,"phrase":"a dime a dozen","meaning_cn":"多得很；不值钱","meaning_en":"Very common; easy to find.","example":"Those fake designer bags are a dime a dozen.","example_cn":"那些假名牌包多如牛毛。"},{"id":588,"phrase":"hit or miss","meaning_cn":"时好时坏；看运气","meaning_en":"Unpredictable; sometimes good, sometimes bad.","example":"Their food is hit or miss depending on the chef.","example_cn":"他们的菜好吃不好吃看厨师。"},{"id":589,"phrase":"go to bat for someone","meaning_cn":"为某人挺身而出；力挺","meaning_en":"To defend or support someone.","example":"My boss went to bat for me during the review.","example_cn":"评审时我老板为我力挺。"},{"id":590,"phrase":"pull yourself together","meaning_cn":"振作起来；冷静下来","meaning_en":"To regain emotional control.","example":"Pull yourself together — the meeting starts in five.","example_cn":"振作点——五分钟后开会。"},{"id":591,"phrase":"off the hook","meaning_cn":"脱身了；解套","meaning_en":"Free from responsibility or trouble.","example":"Mom canceled dinner, so we're off the hook.","example_cn":"妈妈取消了晚饭，我们解脱了。"},{"id":592,"phrase":"off the record","meaning_cn":"不公开；私下说的","meaning_en":"Not for publication or attribution.","example":"Off the record, the merger is happening.","example_cn":"私下说一句，合并确有其事。"},{"id":593,"phrase":"on the same page","meaning_cn":"想法一致；在同一频道","meaning_en":"In agreement; having shared understanding.","example":"Let's make sure we're all on the same page.","example_cn":"我们确认一下大家想法一致。"},{"id":594,"phrase":"chip on your shoulder","meaning_cn":"心存不满；爱找茬","meaning_en":"A resentful or combative attitude.","example":"He's had a chip on his shoulder since the demotion.","example_cn":"他被降职后一直心怀不满。"},{"id":595,"phrase":"bury the hatchet","meaning_cn":"握手言和；化解恩怨","meaning_en":"To make peace.","example":"It's time we buried the hatchet.","example_cn":"是时候我们握手言和了。"},{"id":596,"phrase":"the cold shoulder","meaning_cn":"故意冷淡；爱搭不理","meaning_en":"Deliberately unfriendly treatment.","example":"She gave him the cold shoulder at the party.","example_cn":"她在派对上对他爱搭不理。"},{"id":597,"phrase":"devil's advocate","meaning_cn":"唱反调的人；故意反驳以测试观点","meaning_en":"Someone who argues an opposing view to test an idea.","example":"Let me play devil's advocate here.","example_cn":"我来故意唱个反调。"},{"id":598,"phrase":"fall through the cracks","meaning_cn":"被忽略；漏网","meaning_en":"To be overlooked or forgotten.","example":"Some cases always fall through the cracks.","example_cn":"总有一些案件会被遗漏。"},{"id":599,"phrase":"fish out of water","meaning_cn":"如鱼离水；格格不入","meaning_en":"Someone out of their natural element.","example":"He felt like a fish out of water at the gala.","example_cn":"他在晚会上觉得格格不入。"},{"id":600,"phrase":"from scratch","meaning_cn":"从零开始；从头做起","meaning_en":"Made from the very beginning with basic materials.","example":"She baked the bread from scratch.","example_cn":"她从头开始烤了这个面包。"},{"id":601,"phrase":"get your act together","meaning_cn":"整顿好自己；振作起来","meaning_en":"To organize yourself and behave properly.","example":"You need to get your act together before the deadline.","example_cn":"截止日期前你必须振作起来。"},{"id":602,"phrase":"go cold turkey","meaning_cn":"一下子戒掉；突然停止","meaning_en":"To quit something abruptly.","example":"He quit smoking cold turkey.","example_cn":"他一下子就把烟戒了。"},{"id":603,"phrase":"go against the grain","meaning_cn":"反其道而行之；不循常规","meaning_en":"To go contrary to convention.","example":"Her ideas always go against the grain.","example_cn":"她的想法总是反其道而行之。"},{"id":604,"phrase":"hit rock bottom","meaning_cn":"跌入谷底；到了低谷","meaning_en":"To reach the lowest point.","example":"After losing everything he hit rock bottom.","example_cn":"失去一切后他跌入了人生谷底。"},{"id":605,"phrase":"in a pinch","meaning_cn":"紧要关头；临时应急","meaning_en":"In an emergency or difficult spot.","example":"In a pinch, a paperclip works as a key.","example_cn":"紧急时刻，一枚回形针也能当钥匙。"},{"id":606,"phrase":"in good hands","meaning_cn":"交给可靠的人；放心","meaning_en":"Being well cared for by a competent person.","example":"Don't worry, you're in good hands with Dr. Lee.","example_cn":"放心，李医生会好好照顾你。"},{"id":607,"phrase":"jump ship","meaning_cn":"跳槽；弃船而逃","meaning_en":"To abandon a team or organization.","example":"Several employees jumped ship after the merger.","example_cn":"合并后好几位员工跳槽走了。"},{"id":608,"phrase":"let the chips fall where they may","meaning_cn":"听天由命；顺其自然","meaning_en":"To accept whatever happens.","example":"Tell the truth and let the chips fall where they may.","example_cn":"实话实说，后果如何顺其自然。"},{"id":609,"phrase":"like a deer in the headlights","meaning_cn":"吓呆了；不知所措","meaning_en":"Frozen with fear or shock.","example":"When called on, he froze like a deer in the headlights.","example_cn":"被点名时他像只惊慌的鹿一样愣在原地。"},{"id":610,"phrase":"long story short","meaning_cn":"长话短说；总之","meaning_en":"Quickly summarizing.","example":"Long story short, we got the contract.","example_cn":"长话短说，我们拿下了合同。"},{"id":611,"phrase":"lose your marbles","meaning_cn":"疯了；失去理智","meaning_en":"To lose your sanity or composure.","example":"Have you lost your marbles? That's dangerous!","example_cn":"你疯了吗？那太危险了！"},{"id":612,"phrase":"lose your touch","meaning_cn":"手艺生疏；不灵了","meaning_en":"To lose a skill you once had.","example":"He hasn't lost his touch at chess.","example_cn":"他下棋的本事一点没退步。"},{"id":613,"phrase":"make waves","meaning_cn":"兴风作浪；搞出动静","meaning_en":"To cause a stir or controversy.","example":"Her book really made waves in the industry.","example_cn":"她的书在业内激起了不小的波澜。"},{"id":614,"phrase":"off the beaten path","meaning_cn":"冷门的；人迹罕至的","meaning_en":"Not commonly traveled; unusual.","example":"We found a restaurant off the beaten path.","example_cn":"我们找到了一家冷门的餐厅。"},{"id":615,"phrase":"on cloud nine","meaning_cn":"开心至极；在九霄云外","meaning_en":"Extremely happy.","example":"She's been on cloud nine since the engagement.","example_cn":"订婚后她一直开心得像飞了起来。"},{"id":616,"phrase":"on the tip of my tongue","meaning_cn":"话到嘴边；就差那么一点","meaning_en":"Almost remembered but not quite.","example":"Her name is on the tip of my tongue.","example_cn":"她的名字就在嘴边却想不起来。"},{"id":617,"phrase":"out of the loop","meaning_cn":"被排除在外；信息不通","meaning_en":"Not informed about what's happening.","example":"Since the move I've been out of the loop.","example_cn":"搬家以后我就不知道那边的消息了。"},{"id":618,"phrase":"over your head","meaning_cn":"超出能力；听不懂","meaning_en":"Beyond your understanding or ability.","example":"This math is over my head.","example_cn":"这道数学题超出我的能力范围。"},{"id":619,"phrase":"paint the town red","meaning_cn":"彻夜狂欢；尽情庆祝","meaning_en":"To celebrate wildly.","example":"Let's paint the town red tonight!","example_cn":"今晚我们痛痛快快玩一场！"},{"id":620,"phrase":"pay lip service","meaning_cn":"口头敷衍；嘴上说说","meaning_en":"To support only in words, not action.","example":"The company only pays lip service to diversity.","example_cn":"公司在多元化方面只是嘴上说说。"},{"id":621,"phrase":"a piece of work","meaning_cn":"难搞的家伙；奇葩","meaning_en":"Someone strange or difficult.","example":"Your uncle is a piece of work.","example_cn":"你那个叔叔真是个奇葩。"},{"id":622,"phrase":"play it by ear","meaning_cn":"随机应变；走一步看一步","meaning_en":"To decide as things unfold.","example":"We don't have a plan — we'll play it by ear.","example_cn":"我们没计划——走一步看一步吧。"},{"id":623,"phrase":"pot calling the kettle black","meaning_cn":"五十步笑百步；半斤八两","meaning_en":"Accusing someone of something you're guilty of.","example":"You call me lazy? That's the pot calling the kettle black.","example_cn":"你说我懒？真是半斤八两。"},{"id":624,"phrase":"put your foot down","meaning_cn":"坚决拒绝；态度强硬","meaning_en":"To firmly refuse or insist.","example":"Mom finally put her foot down about screen time.","example_cn":"妈妈终于对看屏幕的时间下了硬性规定。"},{"id":625,"phrase":"raise eyebrows","meaning_cn":"令人侧目；引人惊讶","meaning_en":"To cause surprise or mild disapproval.","example":"His comments raised eyebrows at the meeting.","example_cn":"他的发言令人侧目。"},{"id":626,"phrase":"take a rain check","meaning_cn":"改天再约；下次再说","meaning_en":"To postpone an offer to another time.","example":"I'll take a rain check on dinner tonight.","example_cn":"今晚的饭改天再约吧。"},{"id":627,"phrase":"ring a bell","meaning_cn":"有点耳熟；想起来了","meaning_en":"To sound familiar.","example":"That name rings a bell, but I can't place it.","example_cn":"那个名字有点耳熟，但我想不起来。"},{"id":628,"phrase":"sit tight","meaning_cn":"稳住别动；耐心等","meaning_en":"To wait patiently.","example":"Sit tight — we'll have an update soon.","example_cn":"稳住——我们很快会有新消息。"},{"id":629,"phrase":"skeleton in the closet","meaning_cn":"不可告人的秘密","meaning_en":"A dark secret.","example":"Every family has a skeleton in the closet.","example_cn":"每个家庭都有不可告人的秘密。"},{"id":630,"phrase":"small potatoes","meaning_cn":"小事一桩；不足挂齿","meaning_en":"Minor or insignificant.","example":"That loss is small potatoes compared to last year's.","example_cn":"那点损失和去年相比是小事一桩。"},{"id":631,"phrase":"sour grapes","meaning_cn":"吃不到葡萄说葡萄酸","meaning_en":"Pretending to dislike what you can't have.","example":"His criticism is just sour grapes.","example_cn":"他的批评不过是吃不到葡萄说葡萄酸。"},{"id":632,"phrase":"stab in the back","meaning_cn":"背后捅刀；背叛","meaning_en":"A betrayal by someone trusted.","example":"That rumor was a real stab in the back.","example_cn":"那个谣言真是背后捅刀。"},{"id":633,"phrase":"stand your ground","meaning_cn":"坚守立场；不退让","meaning_en":"To hold firm in a belief or position.","example":"Even under pressure she stood her ground.","example_cn":"即使在压力下她也坚守立场。"},{"id":634,"phrase":"stick your neck out","meaning_cn":"冒风险；为人出头","meaning_en":"To take a risk for someone or something.","example":"I stuck my neck out to recommend her.","example_cn":"我冒着风险推荐了她。"},{"id":635,"phrase":"tall tale","meaning_cn":"吹牛的故事；荒诞不经","meaning_en":"An exaggerated, unbelievable story.","example":"Grandpa loves telling tall tales.","example_cn":"爷爷很喜欢讲些夸张的故事。"},{"id":636,"phrase":"the best of both worlds","meaning_cn":"两全其美；鱼和熊掌","meaning_en":"Enjoying advantages from two different things.","example":"Working from home gives me the best of both worlds.","example_cn":"在家办公让我享受两全其美的好处。"},{"id":637,"phrase":"the bigger picture","meaning_cn":"大局；全局观","meaning_en":"The overall context or situation.","example":"Don't lose sight of the bigger picture.","example_cn":"别忘了大局。"},{"id":638,"phrase":"the cream of the crop","meaning_cn":"精英中的精英；佼佼者","meaning_en":"The very best of a group.","example":"These interns are the cream of the crop.","example_cn":"这些实习生是万里挑一的精英。"},{"id":639,"phrase":"the real deal","meaning_cn":"真材实料；货真价实","meaning_en":"The genuine, authentic thing.","example":"This jazz band is the real deal.","example_cn":"这支爵士乐队真的是货真价实。"},{"id":640,"phrase":"throw a fit","meaning_cn":"发脾气；闹情绪","meaning_en":"To have a tantrum.","example":"The kid threw a fit at the store.","example_cn":"小孩在商店里闹起了脾气。"},{"id":641,"phrase":"throw caution to the wind","meaning_cn":"豁出去了；不顾一切","meaning_en":"To act without worry about risks.","example":"She threw caution to the wind and quit her job.","example_cn":"她豁出去了，辞了职。"},{"id":642,"phrase":"to make matters worse","meaning_cn":"雪上加霜；更糟的是","meaning_en":"Adding another bad thing.","example":"To make matters worse, it started to rain.","example_cn":"更糟的是，天开始下雨了。"},{"id":643,"phrase":"twist someone's arm","meaning_cn":"强迫；半哄半逼","meaning_en":"To persuade someone to do something.","example":"Okay, you twisted my arm — I'll have another slice.","example_cn":"好吧你让我推辞不过——我再吃一块。"},{"id":644,"phrase":"up and running","meaning_cn":"运行起来；正常运作","meaning_en":"Functioning and operational.","example":"The new website is finally up and running.","example_cn":"新网站终于上线运行了。"},{"id":645,"phrase":"up in arms","meaning_cn":"群情激愤；强烈反对","meaning_en":"Angry and protesting.","example":"Parents were up in arms over the new policy.","example_cn":"家长们对新政策极为不满。"},{"id":646,"phrase":"walk a mile in my shoes","meaning_cn":"设身处地；换位思考","meaning_en":"To try to understand someone's situation.","example":"Don't judge until you walk a mile in my shoes.","example_cn":"没体验过我的处境之前别妄加评判。"},{"id":647,"phrase":"walk the talk","meaning_cn":"言行一致；说到做到","meaning_en":"To do what you say you'll do.","example":"Great leaders walk the talk.","example_cn":"优秀的领导者都言行一致。"},{"id":648,"phrase":"walking on air","meaning_cn":"欣喜若狂；飘飘然","meaning_en":"Extremely happy; blissful.","example":"After the proposal she was walking on air.","example_cn":"求婚之后她幸福得飘飘然。"},{"id":649,"phrase":"water off a duck's back","meaning_cn":"毫不在乎；左耳进右耳出","meaning_en":"Criticism that doesn't affect someone.","example":"His insults are water off a duck's back to me.","example_cn":"他那些侮辱话对我来说毫不在意。"},{"id":650,"phrase":"wear your heart on your sleeve","meaning_cn":"感情外露；心事挂脸上","meaning_en":"To openly show your emotions.","example":"She wears her heart on her sleeve — you always know how she feels.","example_cn":"她感情外露——你总能看出她的心情。"},{"id":651,"phrase":"wing it","meaning_cn":"临场发挥；即兴应付","meaning_en":"To improvise without preparation.","example":"I forgot my notes, so I had to wing it.","example_cn":"我忘带笔记，只好临场发挥了。"},{"id":652,"phrase":"without a hitch","meaning_cn":"顺顺利利；毫无差错","meaning_en":"Smoothly, without problems.","example":"The wedding went off without a hitch.","example_cn":"婚礼举办得顺顺利利。"},{"id":653,"phrase":"worth its weight in gold","meaning_cn":"价值连城；千金难买","meaning_en":"Extremely valuable.","example":"A good mentor is worth their weight in gold.","example_cn":"一位好的导师千金难买。"},{"id":654,"phrase":"you snooze you lose","meaning_cn":"慢了就没了；机不可失","meaning_en":"If you're slow, you miss out.","example":"Last piece of pizza — you snooze you lose.","example_cn":"最后一块披萨——下手慢就没了。"},{"id":655,"phrase":"zero in on","meaning_cn":"锁定；精准对准","meaning_en":"To focus precisely on something.","example":"Police zeroed in on a suspect within hours.","example_cn":"警方几小时内就锁定了嫌疑人。"},{"id":656,"phrase":"apple of my eye","meaning_cn":"掌上明珠；心头肉","meaning_en":"Someone cherished above all.","example":"His daughter is the apple of his eye.","example_cn":"他女儿是他的掌上明珠。"},{"id":657,"phrase":"at loggerheads","meaning_cn":"针锋相对；争执不下","meaning_en":"In fierce disagreement.","example":"The two sides are at loggerheads over the budget.","example_cn":"双方在预算问题上针锋相对。"},{"id":658,"phrase":"at the end of the day","meaning_cn":"说到底；归根结底","meaning_en":"Ultimately; in conclusion.","example":"At the end of the day, family comes first.","example_cn":"说到底，家人最重要。"},{"id":659,"phrase":"best thing since sliced bread","meaning_cn":"自切片面包以来最棒的发明（超赞的东西）","meaning_en":"A fantastic invention or idea.","example":"This app is the best thing since sliced bread.","example_cn":"这个应用简直是天底下最好用的。"},{"id":660,"phrase":"better late than never","meaning_cn":"迟到总比不到好；亡羊补牢","meaning_en":"Doing something late is better than not at all.","example":"You sent the gift in March? Better late than never.","example_cn":"你三月才寄礼物？迟到总比不到强。"},{"id":661,"phrase":"bring home the bacon","meaning_cn":"养家糊口；挣钱养家","meaning_en":"To earn a living.","example":"He works two jobs to bring home the bacon.","example_cn":"他打两份工来养家糊口。"},{"id":662,"phrase":"call it a day","meaning_cn":"收工；到此为止","meaning_en":"To stop working for the day.","example":"Let's call it a day — it's almost midnight.","example_cn":"收工吧——都快半夜了。"},{"id":663,"phrase":"a can of worms","meaning_cn":"棘手的乱摊子；打开潘多拉魔盒","meaning_en":"A complicated, messy problem.","example":"Investigating that account opened a can of worms.","example_cn":"调查那个账户揭开了一堆麻烦。"},{"id":664,"phrase":"chicken out","meaning_cn":"临阵退缩；怂了","meaning_en":"To back out from fear.","example":"He was going to ask her but chickened out.","example_cn":"他本来要问她的但最后怂了。"},{"id":665,"phrase":"cross your fingers","meaning_cn":"祈求好运；祈祷顺利","meaning_en":"To hope for good luck.","example":"I'm crossing my fingers for the job offer.","example_cn":"我在祈祷能拿到这份工作offer。"},{"id":666,"phrase":"cry over spilled milk","meaning_cn":"哭洒掉的奶；于事无补的后悔","meaning_en":"To regret what cannot be undone.","example":"No use crying over spilled milk — move on.","example_cn":"覆水难收——向前看吧。"},{"id":667,"phrase":"curiosity killed the cat","meaning_cn":"好奇害死猫","meaning_en":"Being too nosy can lead to trouble.","example":"Maybe don't ask — curiosity killed the cat.","example_cn":"还是别问了——好奇害死猫。"},{"id":668,"phrase":"a diamond in the rough","meaning_cn":"未经打磨的钻石；璞玉","meaning_en":"A person/thing with hidden potential.","example":"She's a diamond in the rough — needs training.","example_cn":"她是块未经打磨的璞玉——需要培养。"},{"id":669,"phrase":"dog days","meaning_cn":"三伏天；最难熬的夏日","meaning_en":"The hottest, laziest period of summer.","example":"The dog days of August slow everything down.","example_cn":"八月三伏天让一切都慢了下来。"},{"id":670,"phrase":"down the drain","meaning_cn":"付诸东流；白费","meaning_en":"Wasted; ruined.","example":"All my savings went down the drain.","example_cn":"我所有的积蓄都付诸东流。"},{"id":671,"phrase":"down to the wire","meaning_cn":"一直到最后一刻；紧要关头","meaning_en":"Until the very last moment.","example":"The race came down to the wire.","example_cn":"比赛紧张到最后一刻。"},{"id":672,"phrase":"eleventh hour","meaning_cn":"最后关头；紧要关头","meaning_en":"The last possible moment.","example":"They reached a deal at the eleventh hour.","example_cn":"他们在最后关头达成了协议。"},{"id":673,"phrase":"every cloud has a silver lining","meaning_cn":"否极泰来；塞翁失马","meaning_en":"Every bad situation has a good aspect.","example":"She lost her job but found her passion — every cloud has a silver lining.","example_cn":"她丢了工作却找到了热爱——塞翁失马焉知非福。"},{"id":674,"phrase":"fair and square","meaning_cn":"光明正大；公平公正","meaning_en":"Honestly and according to the rules.","example":"We won the contract fair and square.","example_cn":"我们光明正大地拿下了合同。"},{"id":675,"phrase":"flip out","meaning_cn":"情绪失控；抓狂","meaning_en":"To lose control emotionally.","example":"Mom flipped out when she saw the mess.","example_cn":"妈妈看到那一团乱就抓狂了。"},{"id":676,"phrase":"foot in the door","meaning_cn":"打开一个缺口；初步进入","meaning_en":"An initial opportunity leading to more.","example":"That internship got me a foot in the door.","example_cn":"那次实习让我获得了进入行业的敲门砖。"},{"id":677,"phrase":"give someone a run for their money","meaning_cn":"让人一较高下；旗鼓相当","meaning_en":"To provide a challenging competition.","example":"The rookie gave the champ a run for his money.","example_cn":"新秀给了卫冕冠军有力的挑战。"},{"id":678,"phrase":"green with envy","meaning_cn":"嫉妒到发绿；眼红","meaning_en":"Very jealous.","example":"She was green with envy over her sister's promotion.","example_cn":"姐姐升职让她嫉妒得不得了。"},{"id":679,"phrase":"half-baked","meaning_cn":"考虑不周；半生不熟的想法","meaning_en":"Not fully thought out.","example":"Don't pitch a half-baked idea to the board.","example_cn":"别把不成熟的想法拿给董事会。"},{"id":680,"phrase":"head over heels","meaning_cn":"神魂颠倒；爱得死去活来","meaning_en":"Deeply in love.","example":"He fell head over heels for her.","example_cn":"他为她神魂颠倒。"},{"id":681,"phrase":"have a whale of a time","meaning_cn":"玩得非常开心；尽兴而归","meaning_en":"To have an extremely enjoyable or fun time.","example":"The kids had a whale of a time at the amusement park.","example_cn":"孩子们在游乐园玩得非常开心。"}];
